function cat = plural(n)
  mod10 = mod(n, 10);
  mod100 = mod(n, 100);
  if (mod10 == 1 && mod100 != 11)
    cat = "one";
  elseif (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14))
    cat = "few";
  else
    cat = "other";
  endif
endfunction
